code.css:
a {
  color: #9a5a1c;
  text-underline-offset: 3px;
}
a:hover {
  text-decoration: none;
}

img {
  max-width: 100%;
  height: auto;
  border-radius: 6px;
}
figcaption {
  font-size: 13px;
  color: #666;
}

ul {
  padding-left: 1.4em;
}
li {
  margin-bottom: 4px;
}
li::marker {
  color: #b68235;
}

usages.css:
.menu {
  display: flex;
  gap: 16px;
  padding: 0;
  list-style: none;
}

code.css:
.box {
  margin: 24px;
  padding: 12px;
  background: #f6ead8;
  border: 1px solid #b68235;
}
.center {
  width: 220px;
  margin: 24px auto;
}

.row {
  display: flex;
  gap: 12px;
}
.item {
  display: block;
  padding: 16px 24px;
  border: 1px solid #b68235;
}

.container {
  display: flex;
  justify-content: space-between;
  padding: 12px;
  border: 1px dashed #999;
}
.item {
  width: 64px;
  padding: 12px 0;
  text-align: center;
  background: #f6ead8;
}

usages.css:
.center {
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 200px;
}

code.css:
.grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
}
.grid div {
  padding: 16px;
  text-align: center;
  background: #f6ead8;
}

usages.css:
.cards {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
  gap: 24px;
}

code.css:
.box {
  padding: 16px;
  border: 1px solid #b68235;
  border-radius: 12px;
}
.circle {
  width: 80px;
  height: 80px;
  margin-top: 16px;
  display: grid;
  place-items: center;
  background: #f6ead8;
  border-radius: 50%;
}

.btn {
  padding: 12px 24px;
  color: #7d5411;
  background: transparent;
  border: 1px solid #b68235;
  border-radius: 4px;
  transition: background-color 0.3s ease;
}
.btn:hover {
  background-color: #ffe3bf;
}
